CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE FUNCTION public.create_profile_on_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, avatar_url) VALUES (new.id, coalesce(new.raw_user_meta_data->>'full_name', ''), coalesce(new.raw_user_meta_data->>'avatar_url', '')); RETURN new; END $$;
CREATE TRIGGER swarm_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile_on_signup();
CREATE TABLE public.saved_audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, ciphertext text NOT NULL, iv text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.saved_audits TO authenticated;
GRANT ALL ON public.saved_audits TO service_role;
ALTER TABLE public.saved_audits ENABLE ROW LEVEL SECURITY;
CREATE POLICY audits_read_own ON public.saved_audits FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY audits_insert_own ON public.saved_audits FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY audits_delete_own ON public.saved_audits FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE INDEX saved_audits_owner_date ON public.saved_audits(user_id, created_at DESC);
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, org text NOT NULL DEFAULT '', email text NOT NULL, subject text NOT NULL, query_type text NOT NULL, message text NOT NULL, delivery_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.contact_rate_limits (key text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), requests integer NOT NULL DEFAULT 1);
GRANT ALL ON public.contact_rate_limits TO service_role;
ALTER TABLE public.contact_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.allow_contact_submission(rate_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN INSERT INTO public.contact_rate_limits(key) VALUES (rate_key) ON CONFLICT (key) DO UPDATE SET requests = CASE WHEN contact_rate_limits.window_start < now() - interval '1 hour' THEN 1 ELSE contact_rate_limits.requests + 1 END, window_start = CASE WHEN contact_rate_limits.window_start < now() - interval '1 hour' THEN now() ELSE contact_rate_limits.window_start END RETURNING requests INTO n; RETURN n <= 5; END $$;
REVOKE ALL ON FUNCTION public.allow_contact_submission(text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.allow_contact_submission(text) TO service_role;